export const playNotificationChime = () => {
  try {
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    const ctx = new AudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'sine';
    // Gentle dual-tone iOS ping (880Hz -> 1174Hz)
    osc.frequency.setValueAtTime(880, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(1174.66, ctx.currentTime + 0.12);

    gain.gain.setValueAtTime(0.15, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.4);
  } catch {
    // Audio context may be restricted before user interaction
  }
};

const notifySubscribers = () => {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('mfk:notifications-updated'));
  }
};

export const notificationManager = {
  getAll: () => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        return JSON.parse(stored);
      }
      localStorage.setItem(STORAGE_KEY, JSON.stringify(DEFAULT_NOTIFICATIONS));
      return DEFAULT_NOTIFICATIONS;
    } catch {
      return DEFAULT_NOTIFICATIONS;
    }
  },

  getUnreadCount: () => {
    const all = notificationManager.getAll();
    return all.filter(n => !n.is_read).length;
  },

  markAsRead: (id) => {
    const all = notificationManager.getAll();
    const updated = all.map(n => n.id === id ? { ...n, is_read: true } : n);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    notifySubscribers();
    return updated;
  },

  markAllAsRead: () => {
    const all = notificationManager.getAll();
    const updated = all.map(n => ({ ...n, is_read: true }));
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    notifySubscribers();
    return updated;
  },

  delete: (id) => {
    const all = notificationManager.getAll();
    const updated = all.filter(n => n.id !== id);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    notifySubscribers();
    return updated;
  },

  push: ({ title, message, category = 'genel', priority = 'medium', link = null }) => {
    const all = notificationManager.getAll();
    const newItem = {
      id: `notif-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
      title,
      message,
      category,
      priority,
      is_read: false,
      created_at: new Date().toISOString(),
      link
    };
    const updated = [newItem, ...all].slice(0, 50); // Keep last 50
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    playNotificationChime();
    notifySubscribers();
    return newItem;
  },

  sendTestNotification: () => {
    const testSamples = [
      {
        title: '🔔 Canlı Sistem Test Bildirimi',
        message: 'Tebrikler! mFk Farm akıllı bildirim motoru ve sesli uyarı sistemi %100 sorunsuz çalışıyor.',
        category: 'sistem',
        priority: 'high'
      },
      {
        title: '🚨 Ani Süt Karantina Uyarısı',
        message: '#205 Nolu Keçi mastitis tedavisi gördü. 4 gün boyunca sütü ana tanka karışmamalıdır!',
        category: 'karantina',
        priority: 'high',
        link: '/health'
      },
      {
        title: '📋 Yeni Veteriner Vizite Kaydı',
        message: 'Yarın sabah 09:30 için 4 baş hayvan ultrason gebelik kontrolüne ayrıldı.',
        category: 'vizite',
        priority: 'medium',
        link: '/health'
      }
    ];

    const pick = testSamples[Math.floor(Math.random() * testSamples.length)];
    return notificationManager.push(pick);
  }
};

export default notificationManager;
